import { createMiddleware } from "@tanstack/react-start";
import { getSupabaseBrowserConfiguration, supabase } from "./client";

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
export const attachSupabaseAuth = createMiddleware({ type: "function" }).client(
  async ({ next }) => {
    // Public and same-machine demo server functions do not require an account.
    // Avoid constructing the Supabase proxy when this local installation has
    // no account service; authenticated server functions still fail closed in
    // their own requireSupabaseAuth middleware.
    if (!getSupabaseBrowserConfiguration().configured) {
      return next({ headers: {} });
    }
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    });
  },
);
